#!/usr/bin/env bash
# fetch-cms-synthetic.sh — Download CMS's public 2023 synthetic Medicare claims
# for a Million Claim Challenge volume run.
#
# Source: CMS, "Synthetic Medicare Enrollment, Fee-for-Service Claims, and
# Prescription Drug Event" (2023 release, data.cms.gov). CMS publishes the
# files for public use without restriction. They are generated by Synthea and
# describe no real person. CMS's user guide (section 4.4) says the payment
# amounts "do not closely model reality", so a run on them measures volume and
# throughput only: no payment comparison is made.
#
# Downloads carrier (professional), outpatient and inpatient claims plus the
# 2015-2023 beneficiary files into OUT_DIR, gzips them (the validator reads
# .gz), and writes SOURCE.txt with each URL, size and SHA-256.
#
# Usage: OUT_DIR=/tmp/cms ./scripts/demo/gcp/fetch-cms-synthetic.sh
# Optional: CARRIER_URL, OUTPATIENT_URL, INPATIENT_URL override a file's URL.
# A file without a known URL is looked up by name in https://data.cms.gov/data.json.

set -euo pipefail

OUT_DIR="${OUT_DIR:?OUT_DIR is required}"
BASE="https://data.cms.gov/sites/default/files/2023-04"
CATALOG_URL="${CATALOG_URL:-https://data.cms.gov/data.json}"

declare -A URLS=(
  [inpatient.csv]="${INPATIENT_URL:-$BASE/67157de9-d962-4af0-bf0e-3578b3afec58/inpatient.csv}"
  [carrier.csv]="${CARRIER_URL:-}"
  [outpatient.csv]="${OUTPATIENT_URL:-}"
  [beneficiary_2015.csv]="$BASE/d5da04d5-61c8-4174-be11-02d0f58217e7/beneficiary_2015.csv"
  [beneficiary_2016.csv]="$BASE/c401e869-f85e-4c57-a9ae-fa7b982593d6/beneficiary_2016.csv"
  [beneficiary_2017.csv]="$BASE/b70edfc5-cd50-4983-9837-b5ece38d400f/beneficiary_2017.csv"
  [beneficiary_2018.csv]="$BASE/bf7aac0e-3ba3-4e7e-9463-073316a17d8a/beneficiary_2018.csv"
  [beneficiary_2019.csv]="$BASE/7f65254b-174e-4460-aa49-6759ea8397af/beneficiary_2019.csv"
  [beneficiary_2020.csv]="$BASE/74b86018-5148-45bb-87f7-c551eda070d8/beneficiary_2020.csv"
  [beneficiary_2021.csv]="$BASE/98832739-88bd-4243-87fe-ee12b8542baf/beneficiary_2021.csv"
  [beneficiary_2022.csv]="$BASE/831cfb41-3a7a-4ce0-b02f-04d27df56b31/beneficiary_2022.csv"
  [beneficiary_2023.csv]="$BASE/18fe0f5d-4126-432f-b12b-2569db9bdefa/beneficiary_2023.csv"
)

mkdir -p "$OUT_DIR"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

missing=()
for name in "${!URLS[@]}"; do
  [[ -n "${URLS[$name]}" ]] || missing+=("$name")
done
if (( ${#missing[@]} > 0 )); then
  echo "==> Looking up ${missing[*]} in ${CATALOG_URL}"
  curl -fsSL --retry 4 --retry-delay 5 "$CATALOG_URL" -o "$work/catalog.json"
  for name in "${missing[@]}"; do
    # The 2023 synthetic release is the one published under /2023-04/.
    url="$(python3 - "$work/catalog.json" "$name" <<'PY'
import json, sys
catalog, name = sys.argv[1], sys.argv[2]
hits = sorted({
    d.get("downloadURL") or d.get("accessURL") or ""
    for ds in json.load(open(catalog)).get("dataset", [])
    for d in ds.get("distribution", []) or []
    if (d.get("downloadURL") or d.get("accessURL") or "").rsplit("/", 1)[-1].lower() == name
})
hits = [h for h in hits if "/2023-04/" in h] or hits
print(hits[0] if hits else "")
PY
)"
    [[ -n "$url" ]] || { echo "Could not find ${name} in ${CATALOG_URL}; set its *_URL variable" >&2; exit 1; }
    URLS[$name]="$url"
  done
fi

{
  echo "CMS Synthetic Medicare Enrollment, Fee-for-Service Claims, and Prescription Drug Event (2023 release)"
  echo "Publisher: Centers for Medicare & Medicaid Services, data.cms.gov. Public use, no restrictions; synthetic (Synthea), no real beneficiaries."
  echo "Used for volume and throughput only. Payment amounts are not compared (CMS user guide, section 4.4)."
  echo "Downloaded: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo
  printf '%-22s %14s  %-64s  %s\n' file bytes sha256 url
} > "$OUT_DIR/SOURCE.txt"

for name in $(printf '%s\n' "${!URLS[@]}" | sort); do
  url="${URLS[$name]}"
  echo "==> ${name} <- ${url}"
  curl -fsSL --retry 4 --retry-delay 10 "$url" -o "$work/$name"
  first="$(head -n 1 "$work/$name" | cut -c1-200)"
  [[ "$first" == *BENE_ID* ]] \
    || { echo "${name} does not look like a CMS synthetic file (first line: ${first})" >&2; exit 1; }
  bytes="$(stat -c %s "$work/$name")"
  sum="$(sha256sum "$work/$name" | cut -d' ' -f1)"
  printf '%-22s %14s  %s  %s\n' "$name" "$bytes" "$sum" "$url" >> "$OUT_DIR/SOURCE.txt"
  gzip -1 -c "$work/$name" > "$OUT_DIR/$name.gz"
  rm -f "$work/$name"
done

cat "$OUT_DIR/SOURCE.txt"
du -sh "$OUT_DIR"
